    col_unique = [len(set(grid[r][c] for r in range(h))) for c in range(w)]

    row_vars = [i for i in range(h) if row_unique[i] > 1]
    col_vars = [i for i in range(w) if col_unique[i] > 1]

    if len(row_vars) == 1:
        feature_type, feature_idx = 'row', row_vars[0]
    elif len(col_vars) == 1:
        feature_type, feature_idx = 'col', col_vars[0]
    else:
        feature_type, feature_idx = 'row', row_vars[0] if row_vars else col_vars[0]

    if feature_type == 'row':
        pattern = list(grid[feature_idx])
    else:
        pattern = [grid[r][feature_idx] for r in range(h-1, -1, -1)]

    buffer_idx = None
    if feature_type == 'row':
        for offset in [-1, 1]:
            n = feature_idx + offset
            if 0 <= n < h and row_unique[n] == 1:
                buffer_idx = n
                break
    else:
        for offset in [-1, 1]:
            n = feature_idx + offset
            if 0 <= n < w and col_unique[n] == 1:
                buffer_idx = n
                break

    targets = sorted([i for i in range(h if feature_type == 'row' else w) if i != feature_idx and i != buffer_idx])

    result = [row[:] for row in grid]

    for rank, idx in enumerate(targets):
        fill_val = pattern[rank % len(pattern)]
        if feature_type == 'row':
            for c in range(w):
                result[idx][c] = fill_val
        else:
            for r in range(h):
                result[r][idx] = fill_val

    return result
